  const anyDegraded = withEnvelope.some(
    (r) => r.verdictQuality?.status === "DEGRADED" || r.verdictQuality?.chain_health === "degraded",
  );
  const allApproved = withEnvelope.every((r) => r.verdictQuality?.status === "APPROVED");

